create table if not exists public.members(id bigint generated by default as identity primary key,name text unique not null);
create table if not exists public.payments(id bigint generated by default as identity primary key,month text not null,member_name text not null,paid boolean not null default false,amount integer not null default 0,unique(month,member_name));
create table if not exists public.expenses(id bigint generated by default as identity primary key,month text not null,name text not null,amount integer not null,note text,created_at timestamptz default now());
alter table public.members enable row level security;alter table public.payments enable row level security;alter table public.expenses enable row level security;
create policy "public read members" on public.members for select to anon,authenticated using (true);
create policy "public read payments" on public.payments for select to anon,authenticated using (true);
create policy "public read expenses" on public.expenses for select to anon,authenticated using (true);
create policy "public write members" on public.members for all to anon,authenticated using (true) with check (true);
create policy "public write payments" on public.payments for all to anon,authenticated using (true) with check (true);
create policy "public write expenses" on public.expenses for all to anon,authenticated using (true) with check (true);
